// An inline picker avoids native color popovers extending beyond an iPad viewport.
const everydayColors=[['Black','#000000'],['Charcoal','#333333'],['Gray','#888888'],['Light gray','#d1d5db'],['White','#ffffff'],['Cream','#fff3d6'],['Red','#e53935'],['Orange','#f58220'],['Yellow','#ffd43b'],['Pink','#ec4899'],['Purple','#8b5cf6'],['Navy','#243b6b'],['Blue','#3b82f6'],['Sky blue','#87ceeb'],['Teal','#159a9c'],['Green','#4caf50'],['Dark green','#256d3b'],['Brown','#8b5a2b'],['Dark brown','#4b2e20'],['Tan','#c49a6c'],['Beige','#e8d5b5'],['Light skin tone','#f5d0b0'],['Medium skin tone','#bf8964'],['Dark skin tone','#754a36']];
export function installColorPickers(){
for(const id of ['fill','stroke']){
const input=document.getElementById(id),button=document.createElement('button');
button.id=id;button.type='button';button.className='color-button';button.value=input.value;button.alpha=1;button.style.backgroundColor=input.value;button.setAttribute('aria-label',`${id} color`);button.setAttribute('aria-expanded','false');input.replaceWith(button);
const panel=document.createElement('div');panel.className='color-panel';panel.hidden=true;panel.id=`${id}-picker`;button.setAttribute('aria-controls',panel.id);
button.closest('label').after(panel);
panel.innerHTML=`<div class="swatches"></div><label>Hex <input aria-label="${id} hex color" type="text" maxlength="7" spellcheck="false"></label><label>Hue <input aria-label="${id} hue" type="range" min="0" max="360" value="160"></label><label>Saturation <input aria-label="${id} saturation" type="range" min="0" max="100" value="40"></label><label>Lightness <input aria-label="${id} lightness" type="range" min="0" max="100" value="50"></label><label>Transparency <input aria-label="${id} transparency" type="range" min="0" max="100" value="0"></label>`;
const none=document.createElement('button');none.type='button';none.className='no-color';none.textContent=`No ${id}`;none.setAttribute('aria-label',`No ${id}`);panel.prepend(none);
button.setNone=value=>{button.none=value;button.title=value?`No ${id}`:button.value;button.classList.toggle('no-color-selected',value);button.setAttribute('aria-label',`${id} color${value?': none':''}`);none.setAttribute('aria-pressed',String(value));};button.setNone(false);
none.onclick=()=>{button.setNone(true);button.dispatchEvent(new Event('change',{bubbles:true}));};
const hex=panel.querySelector('input[type=text]'),ranges=[...panel.querySelectorAll('input[type=range]')];
const numbers=ranges.map((range,index)=>{range.step='any';const number=document.createElement('input');number.type='number';number.min=range.min;number.max=range.max;number.step='any';number.className='color-value';number.setAttribute('aria-label',`${id} ${['hue','saturation','lightness','transparency'][index]} value`);const suffix=document.createElement('span');suffix.className='color-unit';suffix.textContent=index===0?'°':'%';range.before(number,suffix);return number;});
function gradients(){const [h,s,l]=ranges.map(r=>Number(r.value));ranges[0].style.setProperty('--range-gradient','linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)');ranges[1].style.setProperty('--range-gradient',`linear-gradient(to right, hsl(${h} 0% ${l}%), hsl(${h} 100% ${l}%))`);ranges[2].style.setProperty('--range-gradient',`linear-gradient(to right, #000, hsl(${h} ${s}% 50%), #fff)`);ranges[3].style.setProperty('--range-gradient',`linear-gradient(to right, ${button.value}, transparent)`);numbers.forEach((number,index)=>{if(document.activeElement!==number)number.value=ranges[index].value;});const color=`${button.value}${Math.round(button.alpha*255).toString(16).padStart(2,'0')}`;button.style.backgroundImage=`linear-gradient(${color},${color}),conic-gradient(#fff 25%,#c5d0cc 0 50%,#fff 0 75%,#c5d0cc 0)`;button.style.backgroundSize='auto, 8px 8px';ranges.forEach(r=>r.setAttribute('aria-valuetext',r===ranges[0]?`${r.value} degrees`:`${r.value} percent`));}
function sync(){hex.value=button.value;const [r,g,b]=button.value.match(/[a-f\d]{2}/gi).map(n=>parseInt(n,16)/255),max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min,l=(max+min)/2;let h=0,s=0;if(d){s=d/(1-Math.abs(2*l-1));h=max===r?((g-b)/d)%6:max===g?(b-r)/d+2:(r-g)/d+4;h=(h*60+360)%360;}[h,s*100,l*100].forEach((v,i)=>ranges[i].value=Math.round(v));ranges[3].value=Number(((1-button.alpha)*100).toFixed(4));gradients();}
function set(value,update=true){button.setNone(false);button.value=value;button.style.backgroundColor=value;button.title=value;hex.value=value;if(update)sync();else gradients();button.dispatchEvent(new Event('change',{bubbles:true}));}
button.setColor=(value,alpha=1)=>{button.value=value;button.alpha=alpha;button.style.backgroundColor=value;sync();};
button.onclick=()=>{const show=panel.hidden;document.querySelectorAll('.color-panel').forEach(p=>p.hidden=true);document.querySelectorAll('.color-button').forEach(b=>b.setAttribute('aria-expanded','false'));panel.hidden=!show;button.setAttribute('aria-expanded',String(show));if(show)sync();};
for(const [name,color] of everydayColors){const swatch=document.createElement('button');swatch.type='button';swatch.style.backgroundColor=color;swatch.setAttribute('aria-label',`${id} ${name}`);swatch.title=name;swatch.onclick=()=>{button.alpha=1;set(color);};panel.querySelector('.swatches').append(swatch);}
hex.onchange=()=>{if(/^#[a-f\d]{6}$/i.test(hex.value)){hex.setCustomValidity('');set(hex.value);}else{hex.setCustomValidity('Use six hex digits, such as #52b7a4.');hex.reportValidity();}};
for(const range of ranges.slice(0,3))range.oninput=()=>{const [h,s,l]=ranges.map(r=>Number(r.value)),a=s/100*Math.min(l/100,1-l/100),f=n=>{const k=(n+h/30)%12;return Math.round(255*(l/100-a*Math.max(-1,Math.min(k-3,9-k,1)))).toString(16).padStart(2,'0');};set(`#${f(0)}${f(8)}${f(4)}`,false);};ranges[3].oninput=()=>{button.setNone(false);button.alpha=1-Number(ranges[3].value)/100;gradients();button.dispatchEvent(new Event('change',{bubbles:true}));};numbers.forEach((number,index)=>{function apply(final=false){const value=number.valueAsNumber;if(!Number.isFinite(value)){if(final)number.value=ranges[index].value;return;}const min=Number(number.min),max=Number(number.max);if(!final&&(value<min||value>max))return;ranges[index].value=Math.max(min,Math.min(max,value));if(final)number.value=ranges[index].value;ranges[index].oninput();}number.oninput=()=>apply();number.onchange=()=>apply(true);number.onblur=()=>{if(!number.value||!number.validity.valid)apply(true);};});sync();
}
}
